// CreateSnippet is the resolver for the createSnippet field.
//
// It saves synchronously, queues the AI review, and returns immediately; the
// browser learns the review is ready through the ai_review_ready socket frame.
func (r *mutationResolver) CreateSnippet(ctx context.Context, input model.CreateSnippetInput) (*domain.Snippet, error) {
	me, err := caller(ctx)
	if err != nil {
		return nil, err
	}
	title, lang := strings.TrimSpace(input.Title), strings.TrimSpace(input.Language)
	switch {
	case title == "" || lang == "" || strings.TrimSpace(input.Code) == "":
		return nil, errors.New("title, language and code are required")
	case len(title) > maxTitle:
		return nil, fmt.Errorf("title must be at most %d characters", maxTitle)
	case len(lang) > maxLang:
		return nil, errors.New("invalid language")
	case len(input.Code) > maxCode || (input.PreviousVersion != nil && len(*input.PreviousVersion) > maxCode):
		return nil, fmt.Errorf("code must be at most %d KB", maxCode/1000)
	}
	var prev *string
	if input.PreviousVersion != nil && strings.TrimSpace(*input.PreviousVersion) != "" {
		prev = input.PreviousVersion
	}

	sn, err := r.Store.CreateSnippet(ctx, store.NewSnippet{
		AuthorID: me.UserID, Title: title, Language: lang, Code: input.Code, PreviousVersion: prev,
	})
	if err != nil {
		logErr("createSnippet", err)
		return nil, errors.New("could not save the snippet")
	}

	if r.AI != nil {
		if err := r.AI.Enqueue(ctx, sn.ID, sn.Language, sn.Code); err != nil {
			// The snippet is saved either way; the UI offers Retry.
			logErr("createSnippet: enqueue AI", err, "snippet", sn.ID)
			msg := err.Error()
			sn.AIStatus, sn.AIError = domain.AIStatusFailed, &msg
		} else {
			sn.AIStatus = domain.AIStatusPending
		}
	}
	return r.decorate(sn), nil
}

// AddReview is the resolver for the addReview field.
//
// One mutation does three things: persist the review in MongoDB, push a typed
// review_added frame to every socket in the snippet's room, and record a
// notification for the snippet's author - no message broker involved.
func (r *mutationResolver) AddReview(ctx context.Context, snippetID string, input model.AddReviewInput) (*domain.Review, error) {
	me, err := caller(ctx)
	if err != nil {
		return nil, err
	}
	body := strings.TrimSpace(input.Body)
	switch {
	case body == "":
		return nil, errors.New("review body is required")
	case len(body) > maxReview:
		return nil, fmt.Errorf("review must be at most %d characters", maxReview)
	case input.LineNumber != nil && *input.LineNumber < 1:
		return nil, errors.New("lineNumber must be 1 or greater")
	}

	src, err := r.Store.SnippetSource(ctx, snippetID)
	if err != nil {
		return nil, snippetErr(err)
	}
	review, err := r.Store.AddReview(ctx, store.NewReview{
		SnippetID: snippetID, AuthorID: me.UserID, Body: body,
		LineNumber: input.LineNumber, ParentReviewID: input.ParentReviewID,
	})
	if err != nil {
		if errors.Is(err, store.ErrInvalidID) || strings.Contains(err.Error(), "parent review") {
			return nil, err
		}
		logErr("addReview", err)
		return nil, errors.New("could not save the review")
	}

	// Notify the snippet's author (only when someone else is reviewing).
	// Best-effort: the review is already saved, so a failure here must not
	// fail the mutation.
	if src.AuthorID != me.UserID {
		if err := r.Store.CreateNotification(ctx, src.AuthorID, src.ID, review.ID); err != nil {
			logErr("addReview: notification", err, "snippet", src.ID)
		}
	}

	// Fan out to everyone in the room. The reviewer's own tab receives this too
	// and de-duplicates by id against its optimistic add.
	r.publish(src.ID, ws.NewMessage(ws.TypeReviewAdded, src.ID, review))
	return review, nil
}

// RetryAIReview is the resolver for the retryAIReview field.
func (r *mutationResolver) RetryAIReview(ctx context.Context, snippetID string) (*domain.Snippet, error) {
	me, err := caller(ctx)
	if err != nil {
		return nil, err
	}
	if r.AI == nil {
		return nil, errors.New("AI reviews are not enabled on this server (no GEMINI_API_KEY)")
	}
	src, err := r.Store.SnippetSource(ctx, snippetID)
	if err != nil {
		return nil, snippetErr(err)
	}
	if src.AuthorID != me.UserID {
		return nil, errors.New("only the snippet's author can re-run the AI review")
	}
	if err := r.AI.Enqueue(ctx, src.ID, src.Language, src.Code); err != nil {
		return nil, err
	}
	sn, err := r.Store.GetSnippet(ctx, snippetID)
	if err != nil {
		return nil, snippetErr(err)
	}
	return r.decorate(sn), nil
}

